import{_ as a,o as e,c as d,ag as r}from"./chunks/framework.DMXcdKmJ.js";const o="/induframe-docs/images/login/admin-login.png",_=JSON.parse('{"title":"入口与账号","description":"理解公共入口、管理入口与各自的账号，避免在错误入口登录。","frontmatter":{"title":"入口与账号","description":"理解公共入口、管理入口与各自的账号，避免在错误入口登录。","status":"reviewed","kind":"explanation"},"headers":[],"relativePath":"zh/concepts/access.md","filePath":"zh/核心概念/入口与账号.md"}'),n={name:"zh/concepts/access.md"};function i(s,t,h,c,p,l){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="入口与账号" tabindex="-1">入口与账号 <a class="header-anchor" href="#入口与账号" aria-label="Permalink to &quot;入口与账号&quot;">​</a></h1><p>InduFrame 把平台管理和组织内工作分开。安装完成时终端给出两个地址，使用平台前先确认手中的账号属于哪一种入口。</p><h2 id="公共入口" tabindex="-1">公共入口 <a class="header-anchor" href="#公共入口" aria-label="Permalink to &quot;公共入口&quot;">​</a></h2><p>公共入口面向组织成员，页面标题为“登录工作台”。当前安装使用 HTTPS；实际地址和端口以安装结果为准。</p><p>登录时先选组织，再填写该组织的账号。组织管理员在这里管理组织内的用户、工程和运维；其他成员可见的菜单由角色决定。多个组织可以有同名账号，选择组织是登录的一部分。</p><h2 id="管理入口" tabindex="-1">管理入口 <a class="header-anchor" href="#管理入口" aria-label="Permalink to &quot;管理入口&quot;">​</a></h2><p>管理入口面向平台超级管理员，页面标题为“平台管理员登录”，地址末尾包含 <code>/admin/</code>。它使用安装终端给出的内网地址及管理端口。</p><p>平台超级管理员负责组织和平台级管理。安装时设置的超级管理员密码用于这个入口；它不是默认组织管理员的密码。访问公共地址下的 <code>/admin</code> 不能替代内网管理入口。</p><p><img src="'+o+'" alt="平台管理员登录页面，包含账号、密码和登录按钮"></p><p><em>图：管理入口的平台管理员登录页。</em></p><table tabindex="0"><thead><tr><th>需要完成的任务</th><th>使用的入口</th><th>使用的账号</th></tr></thead><tbody><tr><td>完成首次安全设置</td><td>管理入口</td><td>安装时设置的平台超级管理员</td></tr><tr><td>重置默认组织管理员密码</td><td>管理入口</td><td>平台超级管理员</td></tr><tr><td>打开工程管理</td><td>公共入口</td><td>对应组织中有权限的账号</td></tr><tr><td>日常组织工作</td><td>公共入口</td><td>管理员分配的组织账号</td></tr></tbody></table><h2 id="为什么首次安装后要先做设置" tabindex="-1">为什么首次安装后要先做设置 <a class="header-anchor" href="#为什么首次安装后要先做设置" aria-label="Permalink to &quot;为什么首次安装后要先做设置&quot;">​</a></h2><p>默认组织的初始管理员凭据不能用于人工登录。平台超级管理员需要在“组织管理”中重置它的密码，公共入口才开放。重置完成后，组织管理员使用新密码直接登录。</p><p>安装时由你设置的超级管理员密码无需再次修改。其他带初始或重置密码标记的账号，则按页面要求完成改密后进入系统。</p><h2 id="中心安装与工程运行" tabindex="-1">中心安装与工程运行 <a class="header-anchor" href="#中心安装与工程运行" aria-label="Permalink to &quot;中心安装与工程运行&quot;">​</a></h2><p>工程页面还可能要求自己的工程用户登录，它和进入组织工作台的账号不同。开发预览中的身份选择、组织账号以及正式运行的关系，见<a href="/induframe-docs/zh/concepts/development-and-runtime.html">开发、发布与运行</a>。</p><p>中心提供管理和开发入口。工程运行需要对应的运行环境、基础服务、发布版本和部署配置。默认运行环境及中心内置节点已经存在，也不表示环境基础服务已部署完成。中心安装检查与工程运行检查应分别完成。</p><p>继续阅读<a href="/induframe-docs/zh/installation/first-setup.html">完成首次设置</a>或<a href="/induframe-docs/zh/guide/login.html">登录与退出</a>。</p>',18)])])}const u=a(n,[["render",i]]);export{_ as __pageData,u as default};
